["script"] = "--init:\nlocal combat, instance_container, instance = ...\nlocal total, top, amount = 0, 0, 0\n\n--get the misc actor container\nlocal energy_container = combat:GetActorList ( DETAILS_ATTRIBUTE_ENERGY )\n\n\nlocal TBC_POTION_SPELL_IDS = {\n    [9512] = 7676,  -- Restore Energy  恢复能量\n    [10058] = 8008,  -- Replenish Mana  补充法力\n    [11732] = 9421,  -- Major Healthstone   特效治疗石\n    [16666] = 12662,  -- Demonic Rune    恶魔符文\n    [23476] = 19012,  -- Major Healthstone   特效治疗石\n    [23477] = 19013,  -- Major Healthstone   特效治疗石\n    [27869] = 20520,  -- Dark Rune   黑暗符文\n    [27103] = 22044,  -- Replenish Mana  恢复法力\n    [27235] = 22103,  -- Master Healthstone  极效治疗石\n    [27236] = 22104,  -- Master Healthstone  极效治疗石\n    [27237] = 22105,  -- Master Healthstone  极效治疗石\n    [28527] = 22795,  -- Fel Blossom 野魔花\n    [28726] = 22797,  -- Nightmare Seed  梦魇草\n}\n\n--do the loop:\n\nfor _, player in ipairs ( energy_container ) do\n    \n    --only player in group\n    if (player:IsGroupPlayer()) then\n        \n        local found_potion = false\n        \n        --get the spells\n        local spell_container = player.spells and player.spells._ActorTable\n        if (spell_container) then\n            for spellId, _ in pairs (TBC_POTION_SPELL_IDS) do\n                local potionUsed = spell_container [spellId]\n                \n                if (potionUsed) then\n                    local used = potionUsed.counter\n                    if (used and used > 0) then\n                        total = total + used\n                        found_potion = true\n                        if (used > top) then\n                            top = used\n                        end\n                        \n                        --add amount to the player\n                        instance_container:AddValue (player, used)\n                    end\n                end\n            end\n        end\n        \n        if (found_potion) then\n            amount = amount + 1\n        end\n    end\nend\n\n\n\n\n--return:\nreturn total, top, amount\n\n\n",
